extern u8  bunka_ret_sub_sub_step;
extern u8  yazirushi_cw_disp;
extern s32 pad_trig;

void bunkasai_aisyou_check_main(void) {
    s32 v1;
    s32 a3;
    Buf48 buf1;
    Buf44 buf2;
    Buf16 buf3;
    s32 idx;
    u8 *dst;
    s32 *wsrc;

    buf1 = bunkasai_main7_tbl0;
    buf2 = bunkasai_main7_tbl1;
    buf3 = bunkasai_main7_tbl2;

    switch ((s32)now_sub_sub_step) {
    case 0:
        cd_read_start2(1, 0x801E8000, 19328);
        girl_appear[0] = (u8)((u32)(girl0_flag << 30) >> 31);
        girl_appear[1] = (u8)((u32)(girl1_flag << 30) >> 31);
        girl_appear[2] = (u8)((u32)(girl2_flag << 30) >> 31);
        wsrc = (s32 *)girl_blk;
        dst = (&girl_appear[3]);
        do {
            s32 e0 = wsrc[114];
            s32 e1 = wsrc[128];
            s32 e3 = wsrc[156];
            s32 e2 = wsrc[142];
            {
                dst[0] = (u8)((u32)(e0 << 30) >> 31);
                dst[1] = (u8)((u32)(e1 << 30) >> 31);
                dst[3] = (u8)((u32)(e3 << 30) >> 31);
                dst[2] = (u8)((u32)(e2 << 30) >> 31);
            }
            wsrc += 56;
            dst += 4;
        } while (wsrc != (s32 *)girl_blk_end);
        sub_sub_step_up();
        break;

    case 1:
        if (!(get_CD_State2() & 1)) {
            break;
        }
        bunkasai_fort_bank_set();
        now_serifu_in = 0;
        ss_serifu = bunkasai_serifu_ptr[0];
        ss_serifu_kind = bunkasai_serifu_ptr[1];
        sss_sound = bunkasai_serifu_ptr[2];
        v1 = bunka_girl;
        if (v1 == 255) {
            goto case1_zero;
        }
        if (((u32)basyo_pack >> 12) == 3) {
            goto case1_L2;
        }
        if (get_g_zyotai_low(0) == 4 && ((u32)girl0_basyo >> 4) == 3) {
            goto case1_zero;
        }
    case1_L2:
        if (((u32)basyo_pack >> 12) == 3) {
            idx = 1;
            goto case1_set;
        }
        if (get_g_zyotai_low(2) != 4 || ((u32)girl2_basyo >> 4) != 3) {
            goto case1_one;
        }
    case1_zero:
        now_serifu = 0;
        sub_sub_step_up();
        break;
    case1_one:
        idx = 1;
    case1_set:
        now_serifu = (s16)idx;
        goto_sub_sub_step(5);
        break;

    case 2:
        serifu_run();
        break;

    case 3:
        holiday_switch1();
        break;

    case 4:
        a3 = serifu_no;
        bunka_girl = a3;
        date_name_set(a3 & 0xFF);
        sub_sub_step_up();
        break;

    case 5:
        serifu_run();
        break;

    case 6:
        k_reset(1);
        set_kanji_string(-128, 50, 0, (s32)bunkasai_main7_str0, 0);
        k_disp_start(2);
        sub_sub_step_up();
        break;

    case 7:
        device_cmd_send(1290);
        sub_sub_step_up();
        break;

    case 8:
        v1 = bunka_girl;
        if (v1 != 11) {
            goto c8_else;
        }
        set_kanji_string(-128, 66, 0, date_name_set_tbl0[0], 0);
        goto c8_done;
    c8_else:
        bunka_girl = v1;
        set_kanji_string(-128, 66, 0, date_name_set_tbl0[v1], 0);
    c8_done:
        v1 = bunka_girl;
        set_kanji_string(-72, 66, 0, buf1.w[v1], 0);
        k_disp_start(4);
        bunkasai_wait_cnt = 0;
        sub_sub_step_up();
        break;

    case 9:
        bunkasai_wait_cnt = bunkasai_wait_cnt + 1;
        if (bunkasai_wait_cnt >= 21U) {
            bunkasai_wait_cnt = 0;
            sub_sub_step_up();
        }
        break;

    case 10:
        set_kanji_string(-16, 66, 0, (s32)bunkasai_main7_str1, 0);
        k_disp_start(5);
        sub_sub_step_up();
        break;

    case 11:
        bunkasai_wait_cnt = bunkasai_wait_cnt + 1;
        if (bunkasai_wait_cnt >= 21U) {
            bunkasai_wait_cnt = 0;
            sub_sub_step_up();
        }
        break;

    case 12:
        v1 = bunka_girl;
        if (v1 == 0) {
            goto c12_then;
        }
        if (v1 != 11) {
            goto c12_else;
        }
    c12_then:
        set_kanji_string(40, 66, 0,
                      buf3.w[(s32)((u32)(girl0_birth << 21) >> 30)], 0);
        goto c12_done;
    c12_else:
        wsrc = (s32 *)buf2.w[v1];
        bunka_girl = v1;
        set_kanji_string(40, 66, 0, (s32)wsrc, 0);
    c12_done:
        k_disp_start(6);
        sub_sub_step_up();
        break;

    case 13:
        bunkasai_wait_cnt = bunkasai_wait_cnt + 1;
        if (bunkasai_wait_cnt >= 21U) {
            bunkasai_wait_cnt = 0;
            sub_sub_step_up();
        }
        break;

    case 14:
        device_cmd_send(1290);
        sub_sub_step_up();
        break;

    case 15:
        set_kanji_string(-128, 82, 0, (s32)p_sei, 0);
        set_kanji_string(-72, 82, 0, (s32)p_mei, 0);
        k_disp_start(8);
        bunkasai_wait_cnt = 0;
        sub_sub_step_up();
        break;

    case 16:
        bunkasai_wait_cnt = bunkasai_wait_cnt + 1;
        if (bunkasai_wait_cnt >= 21U) {
            bunkasai_wait_cnt = 0;
            sub_sub_step_up();
        }
        break;

    case 17:
        set_kanji_string(-16, 82, 0, (s32)bunkasai_main7_str2, 0);
        k_disp_start(9);
        sub_sub_step_up();
        break;

    case 18:
        bunkasai_wait_cnt = bunkasai_wait_cnt + 1;
        if (bunkasai_wait_cnt >= 21U) {
            bunkasai_wait_cnt = 0;
            sub_sub_step_up();
        }
        break;

    case 19:
        idx = (s32)((u32)(p_birthday << 21) >> 30);
        a3 = buf3.w[idx];
        set_kanji_string(40, 82, 0, a3, 0);
        k_disp_start(10);
        sub_sub_step_up();
        break;

    case 20:
        bunkasai_wait_cnt = bunkasai_wait_cnt + 1;
        if (bunkasai_wait_cnt >= 16U && check_end_k() != 0) {
            yazirushi_cw_disp = yazirushi_cw_disp ^ 0x80;
            bunkasai_wait_cnt = 0;
        }
        if ((pad_trig & 0xF0) != 0 && check_end_k() != 0) {
            k_reset(1);
            yazirushi_cw_disp = yazirushi_cw_disp & 0x7F;
            sub_sub_step_up();
        }
        break;

    case 21:
        serifu_run();
        break;

    case 22:
        device_cmd_send(1288);
        sub_sub_step_up();
        break;

    case 23:
        bunkasai_wait_cnt = bunkasai_wait_cnt + 1;
        if (bunkasai_wait_cnt >= 61U) {
            a3 = get_bunkasai_table();
            now_serifu = (s16)(a3 + 3);
            a3 = get_bunkasai_table();
            bunka_aisyou = a3;
            device_cmd_send(1292);
            sub_sub_step_up();
        }
        break;

    case 24:
        serifu_run();
        break;

    case 25:
        if (get_g_zyotai_low(0) == 4 && ((u32)girl0_basyo >> 4) == 3) {
            bunka_girl = 0;
        } else if (get_g_zyotai_low(2) == 4 && ((u32)girl2_basyo >> 4) == 3) {
            bunka_girl = 2;
        }
        goto_sub_step(bunka_ret_sub_step);
        goto_sub_sub_step(bunka_ret_sub_sub_step);
        break;

    default:
        game_reset();
        break;
    }
}
